head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF47003.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.fn_getListWrtrptSubmitSchdlYy();
};
scwin.fn_getListWrtrptSubmitSchdlYy = function() {
    var url = "/ListedCompany.do?method=listWrtrptSubmitSchdlYy";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_cmb2.DataID = encodeURI(url);
    dts_cmb2.reset();
};
scwin.fn_Search_Page = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=listComStatWrtrptNsubmit";
    url += "&BAS_YY=" + $c.stf.getObjectValue(cmb_BAS_YY);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search_Page();
};
scwin.dts_MASTER_OnFail = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadError = function() {
    $c.stf.alert_error(dts_MASTER);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_MASTER.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_cmb2_OnLoadCompleted = function(rowcount) {
    scwin.fn_Search_Page();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "기업현황보고서 미제출", "", "8");
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    //fn_Search_Page();

};
